#include <vector>
#include <queue>

using namespace std;

class TopologicalSortTemplate {
public:
    // Kahn's algorithm template for Topological Sorting
    vector<int> sortGraph(int vertices, const vector<vector<int>>& edges) {
        vector<int> sortedOrder;
        if (vertices <= 0) return sortedOrder;

        // Initialize adjacency list and in-degrees
        vector<int> inDegree(vertices, 0);
        vector<vector<int>> graph(vertices);

        // Build the graph
        for (const auto& edge : edges) {
            int parent = edge[0];
            int child = edge[1];
            graph[parent].push_back(child);
            inDegree[child]++;
        }

        // Find all initial sources (nodes with 0 in-degree)
        queue<int> sources;
        for (int i = 0; i < vertices; ++i) {
            if (inDegree[i] == 0) {
                sources.push(i);
            }
        }

        // Process elements
        while (!sources.empty()) {
            int vertex = sources.front();
            sources.pop();
            sortedOrder.push_back(vertex);

            for (int child : graph[vertex]) {
                inDegree[child]--;
                if (inDegree[child] == 0) {
                    sources.push(child);
                }
            }
        }

        // If sortedOrder doesn't contain all vertices, there is a cycle
        if (sortedOrder.size() != vertices) {
            return {};
        }

        return sortedOrder;
    }
};

